import{_ as a,o as e,c as r,ag as d}from"./chunks/framework.DMXcdKmJ.js";const u=JSON.parse('{"title":"卸载平台","description":"先决定是否保留数据，再按提示卸载 InduFrame，并确认结果。","frontmatter":{"title":"卸载平台","description":"先决定是否保留数据，再按提示卸载 InduFrame，并确认结果。","status":"reviewed","kind":"how-to"},"headers":[],"relativePath":"zh/installation/uninstall.md","filePath":"zh/安装运维/卸载平台.md"}'),o={name:"zh/installation/uninstall.md"};function i(n,t,l,s,h,p){return e(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="卸载平台" tabindex="-1">卸载平台 <a class="header-anchor" href="#卸载平台" aria-label="Permalink to &quot;卸载平台&quot;">​</a></h1><p>卸载会停止平台服务，组织成员将无法继续使用。先通知使用者，确认你操作的是正确的服务器。</p><p>本页说明 <strong>v1.0 在已测试的 Ubuntu 24 上</strong>的卸载流程，其他系统尚未测试。</p><h2 id="先决定-以后还要不要这些数据" tabindex="-1">先决定：以后还要不要这些数据 <a class="header-anchor" href="#先决定-以后还要不要这些数据" aria-label="Permalink to &quot;先决定：以后还要不要这些数据&quot;">​</a></h2><table tabindex="0"><thead><tr><th>你的打算</th><th>建议选择</th></tr></thead><tbody><tr><td>暂时停用，或准备在原服务器重装</td><td>保留数据卸载，保存原安装包、原账号和数据</td></tr><tr><td>确定不再需要平台及其数据</td><td>确认备份和删除范围后，再选择删除数据</td></tr><tr><td>还没决定，或不知道数据是否有人需要</td><td>先取消，与数据负责人确认</td></tr></tbody></table><p><strong>保留数据不是备份，删除数据无法撤回。</strong> 当前安装包不提供整个平台的一键备份还原工具，不要在未确认的情况下尝试删除后恢复。</p><p>准备重装时，先阅读<a href="/induframe-docs/zh/installation/reinstall.html">保留数据后重新安装</a>，确认所需条件。</p><h2 id="_1-打开卸载程序" tabindex="-1">1. 打开卸载程序 <a class="header-anchor" href="#_1-打开卸载程序" aria-label="Permalink to &quot;1. 打开卸载程序&quot;">​</a></h2><p>让具备系统管理权限的维护人员，在服务器终端执行卸载脚本。默认程序位置可使用：</p><div class="language-sh vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /opt/induframe/uninstall.sh</span></span></code></pre></div><p>安装时选了其他位置，请替换为实际程序目录。完整安装包仍在时，也可进入该文件夹运行 <code>sudo ./uninstall.sh</code>。</p><p>若询问密码，输入服务器账号密码，不是平台登录密码。先记下终端显示的 <strong>“详细输出”日志路径</strong>。</p><h2 id="_2-回答第一次询问-是否开始卸载" tabindex="-1">2. 回答第一次询问：是否开始卸载 <a class="header-anchor" href="#_2-回答第一次询问-是否开始卸载" aria-label="Permalink to &quot;2. 回答第一次询问：是否开始卸载&quot;">​</a></h2><p>看到 **“确定卸载 InduFrame 中心？”**和 <code>[y/N]</code>：</p><ul><li>输入 <code>y</code> 并回车：继续选择数据处理方式。</li><li>输入 <code>n</code> 或直接回车：取消卸载，平台不会因此停用。</li></ul><h2 id="_3-回答第二次询问-是否删除数据" tabindex="-1">3. 回答第二次询问：是否删除数据 <a class="header-anchor" href="#_3-回答第二次询问-是否删除数据" aria-label="Permalink to &quot;3. 回答第二次询问：是否删除数据&quot;">​</a></h2><p>看到 <strong>“是否同时删除平台数据与运行环境（数据库、对象库、配置、日志、程序目录）？”</strong>：</p><ul><li><strong>要保留数据</strong>：输入 <code>n</code> 或直接回车。卸载会继续，停止服务并保留数据。</li><li><strong>确定删除数据</strong>：输入 <code>y</code>，进入最终确认。</li></ul><div class="warning custom-block"><p class="custom-block-title">两次回车的结果不同</p><p>第一次回车是取消整个卸载；已经确认卸载后，第二次回车会真正卸载服务并保留数据。</p></div><h2 id="_4-只有永久删除时-输入最终确认" tabindex="-1">4. 只有永久删除时，输入最终确认 <a class="header-anchor" href="#_4-只有永久删除时-输入最终确认" aria-label="Permalink to &quot;4. 只有永久删除时，输入最终确认&quot;">​</a></h2><p>终端会提醒“删除的数据无法恢复”，再要求 <strong>“输入 PURGE 确认”</strong>。</p><p>只有输入完全一致的大写 <code>PURGE</code> 才继续删除。输入其他内容或直接回车会取消本次卸载。</p><p>服务器原先就有运行环境时，还可能询问是否连它一起删除。它可能承载其他服务，默认保留；不了解用途时不要同意删除。</p><h2 id="怎样确认卸载完成" tabindex="-1">怎样确认卸载完成 <a class="header-anchor" href="#怎样确认卸载完成" aria-label="Permalink to &quot;怎样确认卸载完成&quot;">​</a></h2><p>等终端明确给出最终结果，不要只凭网页打不开判断。</p><table tabindex="0"><thead><tr><th>你的选择</th><th>应看到的结果</th></tr></thead><tbody><tr><td>取消</td><td>提示“已取消卸载”，不算卸载完成</td></tr><tr><td>保留数据</td><td>提示服务已卸载，配置、数据和运行环境按默认选项保留</td></tr><tr><td>删除数据</td><td>提示服务、数据和平台程序已删除，并说明原有运行环境是否保留</td></tr></tbody></table><p>保留数据卸载仍会清理部分安装设置。以后重装需要再次填写向导，自签名证书也会重新生成，请保管好原账号资料。</p><p>若提示采集数据已单独留存，或还有系统规则需处理，记下位置并交给维护人员。不要把删除成功理解为所有留存事项也已处理完。</p><h2 id="没有成功时怎么办" tabindex="-1">没有成功时怎么办 <a class="header-anchor" href="#没有成功时怎么办" aria-label="Permalink to &quot;没有成功时怎么办&quot;">​</a></h2><p>保留完整提示和“详细输出”日志，停止手工清理，联系维护人员。不要直接删除剩余目录，也不要在卸载未完成时马上重装。</p><p>更多现象见<a href="/induframe-docs/zh/installation/troubleshooting.html">安装常见问题</a>。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p>保留数据卸载成功后，需要恢复使用时按<a href="/induframe-docs/zh/installation/reinstall.html">保留数据后重新安装</a>操作。已删除数据、需要全新安装时，从<a href="/induframe-docs/zh/installation/prepare.html">安装前准备</a>开始。</p>',33)])])}const b=a(o,[["render",i]]);export{u as __pageData,b as default};
